import React from "react";
import { Edit2, Trash2, Briefcase } from "lucide-react";

function JobTable({ jobs, onEdit, onDelete }) {
  const styles = {
    container: {
      backgroundColor: "#fff",
      borderRadius: "8px",
      boxShadow: "0 2px 8px rgba(0,0,0,0.1)",
      overflowX: "auto",
      padding: "10px",
    },
    emptyContainer: {
      padding: "48px",
      textAlign: "center",
      backgroundColor: "#fff",
      borderRadius: "8px",
      boxShadow: "0 2px 8px rgba(0,0,0,0.1)",
    },
    emptyTitle: {
      fontSize: "1.125rem",
      fontWeight: "500",
      color: "#111827",
      marginBottom: "8px",
    },
    emptyText: {
      fontSize: "1rem",
      color: "#4B5563",
      marginBottom: "24px",
    },
    table: {
      width: "100%",
      borderCollapse: "collapse",
    },
    thead: {
      backgroundColor: "#F9FAFB",
    },
    th: {
      textAlign: "left",
      fontSize: "0.75rem",
      fontWeight: "500",
      color: "#6B7280",
      textTransform: "uppercase",
      letterSpacing: "0.05em",
      padding: "12px",
    },
    td: {
      padding: "12px",
      fontSize: "0.875rem",
      color: "#374151",
      verticalAlign: "top",
    },
    jobTypeBadge: {
      display: "inline-block",
      padding: "2px 8px",
      fontSize: "0.75rem",
      fontWeight: "500",
      borderRadius: "9999px",
      backgroundColor: "#DBEAFE", // blue-100
      color: "#1E40AF", // blue-800
    },
    actionButton: {
      border: "none",
      background: "none",
      cursor: "pointer",
      padding: "4px",
    },
    actionWrapper: {
      display: "flex",
      gap: "8px",
    },
    rowHover: {
      transition: "background 0.2s",
    },
  };

  if (jobs.length === 0) {
    return (
      <div style={styles.emptyContainer}>
        <Briefcase size={64} color="#D1D5DB" style={{ marginBottom: "16px" }} />
        <h3 style={styles.emptyTitle}>No jobs posted yet</h3>
        <p style={styles.emptyText}>Get started by adding your first job posting</p>
      </div>
    );
  }

  return (
    <div style={styles.container}>
      <table style={styles.table}>
        <thead style={styles.thead}>
          <tr>
            {["Job Title", "Role", "Location", "CTC", "Type", "Posted", "Actions"].map((col) => (
              <th key={col} style={styles.th}>{col}</th>
            ))}
          </tr>
        </thead>
        <tbody>
          {jobs.map((job) => (
            <tr key={job.id} style={styles.rowHover}>
              <td style={styles.td}>
                <div style={{ fontWeight: "500", color: "#111827" }}>{job.title}</div>
                <div style={{ fontSize: "0.875rem", color: "#6B7280" }}>{job.skillset}</div>
              </td>
              <td style={styles.td}>{job.role}</td>
              <td style={styles.td}>{job.location}</td>
              <td style={styles.td}>{job.ctc}</td>
              <td style={styles.td}>
                <span style={styles.jobTypeBadge}>{job.jobType}</span>
              </td>
              <td style={{ ...styles.td, color: "#6B7280" }}>{job.createdAt}</td>
              <td style={styles.td}>
                <div style={styles.actionWrapper}>
                  <button onClick={() => onEdit(job)} style={styles.actionButton}>
                    <Edit2 size={16} color="#2563EB" />
                  </button>
                  <button onClick={() => onDelete(job.id)} style={styles.actionButton}>
                    <Trash2 size={16} color="#DC2626" />
                  </button>
                </div>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

export default JobTable;
